import logging
from datetime import datetime

logger = logging.getLogger("agent-monitor")

class SessionMonitor:
  """Track key metrics for each agent session."""

  def __init__(self, session_id: str):
      self.session_id = session_id
      self.start_time = datetime.now()
      self.turn_count = 0
      self.tool_calls = 0
      self.tool_failures = 0

  def on_turn_complete(self, latency_ms: float):
      self.turn_count += 1
      logger.info(
          "turn_complete",
          extra={
              "session_id": self.session_id,
              "turn": self.turn_count,
              "latency_ms": latency_ms,
          },
      )

  def on_tool_call(self, tool_name: str, success: bool, duration_ms: float):
      self.tool_calls += 1
      if not success:
          self.tool_failures += 1
      logger.info(
          "tool_call",
          extra={
              "session_id": self.session_id,
              "tool": tool_name,
              "success": success,
              "duration_ms": duration_ms,
          },
      )

  def on_session_end(self):
      duration = (datetime.now() - self.start_time).total_seconds()
      logger.info(
          "session_end",
          extra={
              "session_id": self.session_id,
              "duration_seconds": duration,
              "turns": self.turn_count,
              "tool_calls": self.tool_calls,
              "tool_failures": self.tool_failures,
          },
      )

import { Logger } from "pino";

class SessionMonitor {
private sessionId: string;
private startTime: number;
private turnCount = 0;
private toolCalls = 0;
private toolFailures = 0;

constructor(
  sessionId: string,
  private logger: Logger
) {
  this.sessionId = sessionId;
  this.startTime = Date.now();
}

onTurnComplete(latencyMs: number): void {
  this.turnCount++;
  this.logger.info({
    event: "turn_complete",
    sessionId: this.sessionId,
    turn: this.turnCount,
    latencyMs,
  });
}

onToolCall(toolName: string, success: boolean, durationMs: number): void {
  this.toolCalls++;
  if (!success) this.toolFailures++;
  this.logger.info({
    event: "tool_call",
    sessionId: this.sessionId,
    tool: toolName,
    success,
    durationMs,
  });
}

onSessionEnd(): void {
  const durationSeconds = (Date.now() - this.startTime) / 1000;
  this.logger.info({
    event: "session_end",
    sessionId: this.sessionId,
    durationSeconds,
    turns: this.turnCount,
    toolCalls: this.toolCalls,
    toolFailures: this.toolFailures,
  });
}
}
